script.setup:
// Babylon.js renders into the scene's own WebGL2 context: a PBR material study lit by a
// procedural studio environment (a reflection probe captures it once for IBL), with
// GPU particles, soft shadows and Babylon's default post pipeline (bloom, ACES, grain).
const B = await ctx.utils.import("https://esm.sh/@babylonjs/core@9.28.0");
// Passing the context (not the canvas) keeps Babylon from hooking input events.
const [w0, h0] = ctx.resolution;
const engine = new B.Engine(ctx.gl, true, { stencil: true, doNotHandleContextLost: true }, false);
// The engine sizes the canvas from its CSS size on creation; keep the runtime's size instead.
engine.setSize(w0, h0);
const scene = new B.Scene(engine);
scene.useRightHandedSystem = true; // matches ctx.utils.createOrbitCamera
const bgColor = new B.Color3(0.028, 0.03, 0.038);
const bgLinear = bgColor.toLinearSpace();
scene.clearColor = new B.Color4(bgLinear.r, bgLinear.g, bgLinear.b, 1);
scene.ambientColor = B.Color3.Black();
scene.fogMode = B.Scene.FOGMODE_EXP2;
scene.fogColor = bgColor;
scene.fogDensity = 0.045;

const camera = new B.FreeCamera("camera", new B.Vector3(0, 3, 10), scene);
camera.minZ = 0.1; camera.maxZ = 200;

// Procedural studio: dark cyclorama with softboxes, rendered only into the probe.
B.Effect.ShadersStore.studioSkyVertexShader = `precision highp float;
attribute vec3 position; uniform mat4 worldViewProjection; varying vec3 vDir;
void main() { vDir = position; gl_Position = worldViewProjection * vec4(position, 1.0); }`;
B.Effect.ShadersStore.studioSkyFragmentShader = `precision highp float;
varying vec3 vDir; uniform vec3 accent;
float box(vec3 d, vec3 c, vec2 size) {
  vec3 z = normalize(c), x = normalize(cross(vec3(0.0, 1.0, 0.0), z)), y = cross(z, x);
  float f = dot(d, z); if (f <= 0.0) return 0.0;
  vec2 p = vec2(dot(d, x), dot(d, y)) / f;
  vec2 q = smoothstep(size, size * 0.8, abs(p));
  return q.x * q.y;
}
void main() {
  vec3 d = normalize(vDir);
  vec3 col = mix(vec3(0.010, 0.010, 0.012), vec3(0.05, 0.055, 0.07), smoothstep(-0.2, 0.6, d.y));
  col += vec3(12.0) * box(d, vec3(0.0, 1.0, 0.08), vec2(0.7, 0.45));      // overhead softbox
  col += vec3(9.0, 8.0, 6.6) * box(d, vec3(0.9, 0.35, 0.55), vec2(0.25, 0.7)); // warm key strip
  col += accent * 8.0 * box(d, vec3(-0.85, 0.25, -0.6), vec2(0.16, 0.8));  // colored rim strip
  col += vec3(2.0, 2.6, 3.6) * box(d, vec3(-0.7, 0.3, 0.75), vec2(0.45, 0.3)); // cool fill
  gl_FragColor = vec4(col, 1.0);
}`;
const skyMat = new B.ShaderMaterial("studioSky", scene, { vertex: "studioSky", fragment: "studioSky" }, { attributes: ["position"], uniforms: ["worldViewProjection", "accent"] });
skyMat.backFaceCulling = false;
skyMat.fogEnabled = false;
const sky = B.MeshBuilder.CreateSphere("sky", { diameter: 80, segments: 32, sideOrientation: B.Mesh.BACKSIDE }, scene);
sky.material = skyMat;
sky.infiniteDistance = true;
sky.layerMask = 0x10000000; // the main camera (0x0fffffff) never sees it
const probe = new B.ReflectionProbe("studio", 256, scene, true, true, true);
probe.renderList.push(sky);
probe.position = new B.Vector3(0, 1, 0);
probe.refreshRate = B.RenderTargetTexture.REFRESHRATE_RENDER_ONCE;
scene.environmentTexture = probe.cubeTexture;
scene.environmentIntensity = 1.3;

// Key light with soft shadows.
const sun = new B.DirectionalLight("key", new B.Vector3(-0.55, -1, -0.35), scene);
sun.position = new B.Vector3(6, 12, 4);
sun.intensity = 2.2;
sun.diffuse = new B.Color3(1, 0.95, 0.88);
const shadows = new B.ShadowGenerator(2048, sun);
shadows.usePercentageCloserFiltering = true;
shadows.filteringQuality = B.ShadowGenerator.QUALITY_HIGH;
shadows.bias = 0.002; shadows.normalBias = 0.02;

const pbr = (name, setup) => {
  const m = new B.PBRMaterial(name, scene);
  m.realTimeFiltering = true; // blur the probe by roughness on the fly
  setup(m);
  return m;
};
const floorMat = pbr("floor", (m) => { m.albedoColor = new B.Color3(0.03, 0.032, 0.04); m.metallic = 0; m.roughness = 0.32; });
const floor = B.MeshBuilder.CreateDisc("floor", { radius: 40, tessellation: 96 }, scene);
floor.rotation.x = Math.PI / 2;
floor.material = floorMat;
floor.receiveShadows = true;

// Hero: an iridescent metal knot.
const knotMat = pbr("knot", (m) => {
  m.albedoColor = new B.Color3(0.92, 0.9, 0.86); m.metallic = 1; m.roughness = 0.18;
  m.iridescence.isEnabled = true; m.iridescence.intensity = 1; m.iridescence.indexOfRefraction = 1.8;
  m.iridescence.minimumThickness = 100; m.iridescence.maximumThickness = 450;
});
const knot = B.MeshBuilder.CreateTorusKnot("knot", { radius: 1.05, tube: 0.34, radialSegments: 256, tubularSegments: 48, p: 2, q: 3 }, scene);
knot.material = knotMat;
knot.position.y = 1.85;
shadows.addShadowCaster(knot);
const plinth = B.MeshBuilder.CreateCylinder("plinth", { diameter: 2.2, height: 0.22, tessellation: 96 }, scene);
plinth.position.y = 0.11;
plinth.material = pbr("plinth", (m) => { m.albedoColor = new B.Color3(0.02, 0.02, 0.022); m.metallic = 0; m.roughness = 0.08; m.clearCoat.isEnabled = true; });
plinth.receiveShadows = true;
shadows.addShadowCaster(plinth);

// A ring of spheres, one PBR feature each.
const looks = [
  ["gold", (m) => { m.albedoColor = new B.Color3(1.0, 0.76, 0.34); m.metallic = 1; m.roughness = 0.2; }],
  ["paint", (m) => { m.albedoColor = new B.Color3(0.7, 0.05, 0.08); m.metallic = 0.3; m.roughness = 0.45; m.clearCoat.isEnabled = true; m.clearCoat.intensity = 1; m.clearCoat.roughness = 0.03; }],
  ["brushed", (m) => { m.albedoColor = new B.Color3(0.95, 0.64, 0.54); m.metallic = 1; m.roughness = 0.35; m.anisotropy.isEnabled = true; m.anisotropy.intensity = 0.9; }],
  ["velvet", (m) => { m.albedoColor = new B.Color3(0.05, 0.06, 0.25); m.metallic = 0; m.roughness = 0.9; m.sheen.isEnabled = true; m.sheen.intensity = 1; m.sheen.color = new B.Color3(0.55, 0.65, 1); m.sheen.roughness = 0.4; }],
  ["glass", (m) => { m.albedoColor = new B.Color3(1, 1, 1); m.metallic = 0; m.roughness = 0.02; m.subSurface.isRefractionEnabled = true; m.subSurface.indexOfRefraction = 1.45; m.subSurface.tintColor = new B.Color3(0.75, 0.95, 0.9); }],
  ["chrome", (m) => { m.albedoColor = new B.Color3(0.96, 0.96, 0.97); m.metallic = 1; m.roughness = 0.04; }],
  ["ceramic", (m) => { m.albedoColor = new B.Color3(0.9, 0.88, 0.84); m.metallic = 0; m.roughness = 0.3; m.clearCoat.isEnabled = true; m.clearCoat.roughness = 0.1; }],
];
const ring = new B.TransformNode("ring", scene);
const mats = {};
looks.forEach(([name, setup], i) => {
  const m = pbr(name, setup);
  mats[name] = m;
  const a = (i / looks.length) * Math.PI * 2;
  const ball = B.MeshBuilder.CreateSphere(name, { diameter: 1.1, segments: 64 }, scene);
  ball.material = m;
  ball.parent = ring;
  ball.position.set(Math.cos(a) * 3.4, 0.55, Math.sin(a) * 3.4);
  shadows.addShadowCaster(ball);
});

// GPU particles: warm sparks drifting up through procedural noise.
const sparkTex = new B.DynamicTexture("spark", 64, scene, false);
const g = sparkTex.getContext();
const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
grad.addColorStop(0, "rgba(255,255,255,1)"); grad.addColorStop(0.25, "rgba(255,255,255,0.6)"); grad.addColorStop(1, "rgba(255,255,255,0)");
g.fillStyle = grad; g.fillRect(0, 0, 64, 64);
sparkTex.hasAlpha = true;
sparkTex.update();
const useGpu = B.GPUParticleSystem.IsSupported;
const sparks = useGpu ? new B.GPUParticleSystem("sparks", { capacity: 40000 }, scene) : new B.ParticleSystem("sparks", 8000, scene);
sparks.particleTexture = sparkTex;
sparks.emitter = new B.Vector3(0, 0.05, 0);
sparks.createDirectedCylinderEmitter(5.6, 0.1, 0.35, new B.Vector3(-0.15, 1, -0.15), new B.Vector3(0.15, 1, 0.15));
sparks.minEmitPower = 0.6; sparks.maxEmitPower = 1.6;
sparks.minLifeTime = 2.5; sparks.maxLifeTime = 5;
sparks.minSize = 0.025; sparks.maxSize = 0.08;
sparks.gravity = new B.Vector3(0, 0.25, 0);
sparks.blendMode = B.ParticleSystem.BLENDMODE_ADD;
sparks.colorDead = new B.Color4(0, 0, 0, 0);
const noise = new B.NoiseProceduralTexture("sparkNoise", 128, scene);
noise.animationSpeedFactor = 3; noise.persistence = 1.4; noise.brightness = 0.5; noise.octaves = 3;
sparks.noiseTexture = noise;
sparks.noiseStrength = new B.Vector3(0.5, 0.2, 0.5);
sparks.preWarmCycles = 200; sparks.preWarmStepOffset = 5;
sparks.start();

// Default post pipeline: HDR, MSAA, bloom, ACES tone mapping, vignette, grain.
const pipe = new B.DefaultRenderingPipeline("post", true, scene, [camera]);
pipe.samples = 4;
pipe.bloomEnabled = true; pipe.bloomThreshold = 0.85; pipe.bloomKernel = 96; pipe.bloomScale = 0.5;
pipe.imageProcessingEnabled = true;
const ip = pipe.imageProcessing;
ip.toneMappingEnabled = true;
ip.toneMappingType = B.ImageProcessingConfiguration.TONEMAPPING_ACES;
ip.contrast = 1.25;
ip.vignetteEnabled = true; ip.vignetteWeight = 2.2; ip.vignetteColor = new B.Color4(0, 0, 0, 0);
pipe.grainEnabled = true; pipe.grain.intensity = 4; pipe.grain.animated = true;
pipe.chromaticAberrationEnabled = true; pipe.chromaticAberration.aberrationAmount = 2;

Object.assign(ctx.state, {
  B, engine, scene, camera, knot, ring, mats, knotMat, sparks, pipe, skyMat, probe, size: [0, 0],
  target: new B.Vector3(), accent: new B.Color3(), paint: new B.Color3(), spark: new B.Color4(), sparkCap: useGpu ? 40000 : 8000,
  orbit: ctx.utils.createOrbitCamera({ distance: 11.5, theta: 0.55, phi: 1.17, target: [0, 1.1, 0], fov: 38, near: 0.1, far: 200, minDistance: 3, maxDistance: 40 }),
});

script.render:
const s = ctx.state, u = ctx.uniforms, [w, h] = ctx.resolution, B = s.B;
if (s.size[0] !== w || s.size[1] !== h) {
  s.size = [w, h];
  s.engine.setSize(w, h);
}
// The shared orbit camera drives Babylon's camera.
s.orbit.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
s.camera.fov = (s.orbit.fov * Math.PI) / 180;
s.camera.position.set(...s.orbit.getEye());
s.camera.setTarget(s.target.set(...s.orbit.getTarget()));
// Look controls. Colors from the controls are sRGB; Babylon's material colors are linear.
s.paint.set(...u.u_paint).toLinearSpaceToRef(s.paint);
s.mats.paint.albedoColor.copyFrom(s.paint);
s.skyMat.setColor3("accent", s.accent.set(...u.u_paint).toLinearSpaceToRef(s.accent));
s.knotMat.roughness = u.u_rough;
s.mats.gold.roughness = Math.min(1, u.u_rough + 0.05);
s.mats.brushed.roughness = Math.min(1, u.u_rough + 0.2);
const [sr, sg, sb] = u.u_spark;
s.sparks.color1 = new B.Color4(sr * 6, sg * 6, sb * 6, 1);
s.sparks.color2 = new B.Color4(sr * 2.5, sg * 2, sb * 2, 1);
s.sparks.emitRate = u.u_sparks * s.sparkCap / 60;
s.pipe.imageProcessing.exposure = u.u_exposure;
s.pipe.bloomWeight = u.u_bloom;
const dt = Math.min(ctx.dt, 0.1) * u.u_speed;
s.knot.rotation.y += dt * 0.5;
s.knot.rotation.x = Math.sin(ctx.time * 0.4 * u.u_speed) * 0.25;
s.ring.rotation.y -= dt * 0.15;
// The runtime touched GL state since the last frame; Babylon caches it, so resync first.
s.engine.wipeCaches(true);
s.engine.beginFrame();
s.scene.render();
s.engine.endFrame();
